UPDATE components SET description = 'api.terrascale.tech, the global TerraBase endpoint' WHERE id = '01M4E7G1W82VKFPF5FJ9AVK1D2' AND lower(description) IN (SELECT 'api.terrascale.tech, served from every ' || lower(provider) || '.io region' FROM endpoints WHERE component_id = components.id AND provider NOT IN ('cloudflare', 'other'));
UPDATE regions SET ping_label = 'TerraBase API, gru' WHERE lower(ping_label) IN (SELECT 'terrabase api, nearest ' || lower(provider) || '.io region' FROM endpoints WHERE region_code = regions.code AND provider NOT IN ('cloudflare', 'other'));
UPDATE endpoints SET headers = (SELECT json_group_object(key, value) FROM json_each(endpoints.headers) WHERE lower(key) != lower(endpoints.provider) || '-prefer-region'), url = CASE WHEN component_id = '01M4E7G1W82VKFPF5FJ9AVK1D0' AND url = 'https://ts-terrabase.' || provider || '.dev/health/replication' THEN 'https://api.terrascale.tech/health/replication' ELSE url END, provider = 'other' WHERE provider NOT IN ('cloudflare', 'other');
UPDATE endpoints SET headers = json_set(headers, '$."X-TerraScale-Region-Pin"', lower(region_code)) WHERE url LIKE 'https://api.terrascale.tech/%' AND region_code IS NOT NULL;
DELETE FROM endpoints WHERE id IN ('01M4E7G1W82VKFPF5FJ9AVK1DX', '01M4E7G1W82VKFPF5FJ9AVK1DZ') AND url = 'https://auth.terrascale.tech/readyz';
UPDATE endpoints SET assertions = '[{"path":"status","op":"eq","value":"ready"}]' WHERE id = '01M4E7G1W82VKFPF5FJ9AVK1D6' AND assertions = '[{"path":"status","op":"eq","value":"ready"},{"path":"region","op":"eq","value":"gru"}]';
UPDATE endpoints SET url = 'https://api.terrascale.tech/v1/projects/01M4E7G1W82VKFPF5FJ9AVK1DT/databases/status_canary/collections/canary/documents/by-key?id=01M4E7G1W82VKFPF5FJ9AVK1DV' WHERE id IN ('01M4E7G1W82VKFPF5FJ9AVK1DB', '01M4E7G1W82VKFPF5FJ9AVK1DC', '01M4E7G1W82VKFPF5FJ9AVK1E0') AND url = 'https://api.terrascale.tech/v1/projects/01M4E7G1W82VKFPF5FJ9AVK1DT/databases/status_canary/collections/canary/documents/01M4E7G1W82VKFPF5FJ9AVK1DV';
UPDATE endpoints SET url = 'https://api.terrascale.tech/v1/projects/01M4E7G1W82VKFPF5FJ9AVK1DT/databases/status_canary' WHERE id IN ('01M4E7G1W82VKFPF5FJ9AVK1DB', '01M4E7G1W82VKFPF5FJ9AVK1DC', '01M4E7G1W82VKFPF5FJ9AVK1E0') AND url = 'https://api.terrascale.tech/v1/projects/01M4E7G1W82VKFPF5FJ9AVK1DT/databases/status_canary/collections/canary/documents/by-key?id=01M4E7G1W82VKFPF5FJ9AVK1DV';
UPDATE endpoints SET url = '/v1/projects/{project}/databases/{database}/sql/execute' WHERE probe = 'documents' AND url = '/v1/projects/{project}/databases/{database}/collections/{collection}';
UPDATE regions SET ping_url = NULL, ping_label = NULL WHERE code IN ('SJC', 'FRA') AND ping_url = 'https://api.terrascale.tech/healthz' AND ping_label = 'TerraBase API, OCI gru';
UPDATE endpoints SET assertions = '[{"path":"status","op":"eq","value":"ok"}]', region_code = NULL, cluster = 'reported peers', indirect = 0, extract = '{"lag":"maxLagSeconds"}' WHERE id = '01M4PVGGBHD58R8HYNDBTGFRGJ' AND url = 'https://api.terrascale.tech/health/replication' AND assertions IN ('[{"path":"status","op":"eq","value":"ok"},{"path":"region","op":"eq","value":"gru"}]', '[{"path":"status","op":"eq","value":"ok"},{"path":"region","op":"eq","value":"gru"},{"path":"peers[0]","op":"exists"},{"path":"maxLagSeconds","op":"gt","value":-1}]', '[{"path":"status","op":"eq","value":"ok"}]');
UPDATE endpoints SET assertions = '[]', indirect = 1, extract = '{"lag":"peers[region=sjc].lagSeconds"}' WHERE id = '01M4PVGGBJ24A140MWGJV7MVKV' AND url = 'https://api.terrascale.tech/health/replication' AND assertions IN ('[{"path":"status","op":"eq","value":"ok"},{"path":"region","op":"eq","value":"sjc"}]', '[{"path":"status","op":"eq","value":"ok"},{"path":"region","op":"eq","value":"sjc"},{"path":"peers[0]","op":"exists"},{"path":"maxLagSeconds","op":"gt","value":-1}]', '[]');
