UPDATE endpoints SET headers = (SELECT json_group_object(key, value) FROM json_each(endpoints.headers) WHERE lower(key) != 'x-terrascale-region-pin') WHERE component_id = '01M4E7G1W82VKFPF5FJ9AVK1D0' AND url = 'https://api.terrascale.tech/health/replication';
UPDATE components SET description = 'api.terrascale.tech, the global TerraBase endpoint' WHERE id = '01M4E7G1W82VKFPF5FJ9AVK1D2' AND description = 'api.terrascale.tech, served from OCI gru';
UPDATE regions SET ping_label = 'TerraBase API, gru' WHERE code = 'GRU' AND ping_label = 'TerraBase API, OCI gru';
